fn probe_begin(probe: Option<(u64, Instant)>) {
    HTTP_STAGE_PROBE.with(|slot| *slot.borrow_mut() = probe.map(|(id, start)| HttpStageProbe { id, start, stages: vec![("worker", start.elapsed().as_nanos())] }));
}
fn probe_mark(stage: &'static str) {
